Batch download (2 files, 4 at a time) — this client cannot run shell commands, so hand this single command to the user to run to save all the files (keep each URL exactly as given — do not strip query parameters, as they are part of the URL signature; prefer it over running each curl separately):
# Download all 2 files (4 at a time) — prefer this single command over running each curl separately:
if (-not (Get-Command curl.exe -ErrorAction SilentlyContinue)) { throw "curl.exe not found" }
$items = @( @{u="https://cloud.comfy.org/api/s/yP2VFTqACQV7FVtxjeTJRw?raw=1";p="$env:USERPROFILE\Downloads\ComfyUI\comfy_output.png"}, @{u="https://cloud.comfy.org/api/s/4-zKX9mTFH-OhblxigRiHw?raw=1";p="$env:USERPROFILE\Downloads\ComfyUI\comfy_output_1.png"} )
if ($PSVersionTable.PSVersion.Major -ge 7) {
  $failed = @($items | ForEach-Object -Parallel { $i = $_; curl.exe -L --fail-with-body --retry 3 --retry-all-errors --retry-delay 1 --connect-timeout 20 --speed-limit 1024 --speed-time 30 --create-dirs -o "$($i.p).part" -- $i.u; if ($LASTEXITCODE -ne 0) { Remove-Item -Force -ErrorAction SilentlyContinue -LiteralPath "$($i.p).part"; $i.u } else { try { Move-Item -Force -ErrorAction Stop -LiteralPath "$($i.p).part" -Destination $i.p } catch { $i.u } } } -ThrottleLimit 4)
} else {
  $failed = @()
  foreach ($i in $items) { curl.exe -L --fail-with-body --retry 3 --retry-all-errors --retry-delay 1 --connect-timeout 20 --speed-limit 1024 --speed-time 30 --create-dirs -o "$($i.p).part" -- $i.u; if ($LASTEXITCODE -ne 0) { Remove-Item -Force -ErrorAction SilentlyContinue -LiteralPath "$($i.p).part"; $failed += $i.u } else { try { Move-Item -Force -ErrorAction Stop -LiteralPath "$($i.p).part" -Destination $i.p } catch { $failed += $i.u } } }
}
if ($failed.Count -gt 0) { throw "$($failed.Count) of 2 download(s) failed: $($failed -join ', ')" }
